; ================================================================
;            PROVIDED TEST HARNESS -- DO NOT EDIT THIS FILE
; ================================================================
; call_binom(n{rdi}, k{rsi}, uint64_t* changed{rdx}) -> rax
; Puts known values in the callee-saved registers, calls binom(n, k), and
; writes to *changed one bit per callee-saved register that binom did not
; preserve: bit 0 rbx, 1 rbp, 2 r12, 3 r13, 4 r14, 5 r15, 6 rsp.
; It restores all of them itself, so test_binom.c keeps working either way.

global call_binom
extern binom

%define S_RBX 0x1111111111111111
%define S_RBP 0x2222222222222222
%define S_R12 0x3333333333333333
%define S_R13 0x4444444444444444
%define S_R14 0x5555555555555555
%define S_R15 0x6666666666666666

section .bss
saved_rsp:  resq 1

section .text
call_binom:
    push    rbx
    push    rbp
    push    r12
    push    r13
    push    r14
    push    r15
    push    rdx                     ; the address for the changed bits
    mov     [rel saved_rsp], rsp
    mov     rbx, S_RBX
    mov     rbp, S_RBP
    mov     r12, S_R12
    mov     r13, S_R13
    mov     r14, S_R14
    mov     r15, S_R15
    call    binom                   ; rax = binom(n, k)

    xor     ecx, ecx                ; rcx = changed bits
    mov     r11, S_RBX
    cmp     rbx, r11
    je      .rbp
    or      rcx, 1
.rbp:
    mov     r11, S_RBP
    cmp     rbp, r11
    je      .r12
    or      rcx, 2
.r12:
    mov     r11, S_R12
    cmp     r12, r11
    je      .r13
    or      rcx, 4
.r13:
    mov     r11, S_R13
    cmp     r13, r11
    je      .r14
    or      rcx, 8
.r14:
    mov     r11, S_R14
    cmp     r14, r11
    je      .r15
    or      rcx, 16
.r15:
    mov     r11, S_R15
    cmp     r15, r11
    je      .rsp
    or      rcx, 32
.rsp:
    cmp     rsp, [rel saved_rsp]
    je      .done
    or      rcx, 64
    mov     rsp, [rel saved_rsp]    ; repair rsp so the pops below work
.done:
    pop     rdx
    mov     [rdx], rcx
    pop     r15
    pop     r14
    pop     r13
    pop     r12
    pop     rbp
    pop     rbx
    ret
